mapper.select:
SELECT 

WHERE o.kind = #{kind}

    AND (o.order_no LIKE CONCAT('%', #{q.orderNo}, '%') OR o.external_no LIKE CONCAT('%', #{q.orderNo}, '%'))

AND o.partner_id = #{q.partnerId}
AND o.status = #{q.status}
AND o.order_date >= #{q.beginDate}
AND o.order_date <= #{q.endDate}

    AND EXISTS (SELECT 1 FROM scm_order_item i JOIN wms_material m ON m.id = i.material_id
                WHERE i.order_id = o.id
                  AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%')))

ORDER BY o.id DESC

SELECT COALESCE(SUM(i.price * o.exchange_rate * GREATEST(i.qty - i.done_qty + i.replenish_qty, 0)), 0)
FROM scm_order o
JOIN scm_order_item i ON i.order_id = o.id
WHERE o.kind = 'SALES' AND o.partner_id = #{customerId} AND o.id <> #{excludeId}
  AND o.status IN #{s}

SELECT i.material_id AS "materialId", SUM(GREATEST(i.qty - i.done_qty + i.replenish_qty, 0)) AS "qty"
FROM scm_order o
JOIN scm_order_item i ON i.order_id = o.id
WHERE o.kind = #{kind}
  AND o.status IN #{s}
  AND i.material_id IN #{id}
GROUP BY i.material_id
